// Destroys the town-portal object (classId 0x3b) owned by the player and its paired destination portal. Fires the A5Q5 Arreat Summit leave callback for each portal, removes them from the dungeon via AllocDrlgDelete and FreeServerUnit, and clears the HasPortal room flag on both sides.
void __fastcall PLAYER_DestroyPortalPair(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2UnitStrc* pPortal;
    D2UnitStrc* pPairedPortal;
    D2RoomStrc* pRoom;
    if (!pUnit) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x25a);
      exit(-1);
    } else {
      D2UnitDataPlayerStrc* pPlayerData;
      pPlayerData = D2Common::Units::GetPlayerData(pUnit);
      if (!pPlayerData) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x25d);
        exit(-1);
      }

      pPortal = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_OBJECT, pPlayerData->dwUniqueId);
      if (!(pPortal && pPortal->nClassId == 0x3b)) {
        return;
      }

      Quests::QUESTS::A5Q5::QUEST_OnPlayerLeaveArreatSummit(pGame, pPortal);
      pPairedPortal = UNIT::SUnit::UNITS_FindPortalOwnerUnit(pGame, pPortal);
      pRoom = D2Common::Units::UNITS_GetRoom(pPortal);
      if (pRoom) {
        D2Common::DUNGEON::Dungeon::AllocDrlgDelete(pRoom, UNIT_OBJECT, pPortal->nUnitGUID);
      }

      UNIT::SUnit::FreeServerUnit(pGame, pPortal);
      D2Common::DUNGEON::Dungeon::ToggleHasPortalFlagRoom(pRoom, 1);
      if (!pPairedPortal) {
        return;
      }

      Quests::QUESTS::A5Q5::QUEST_OnPlayerLeaveArreatSummit(pGame, pPairedPortal);
      pRoom = D2Common::Units::UNITS_GetRoom(pPairedPortal);
      if (pRoom) {
        D2Common::DUNGEON::Dungeon::AllocDrlgDelete(pRoom, UNIT_OBJECT, pPairedPortal->nUnitGUID);
      }

      UNIT::SUnit::FreeServerUnit(pGame, pPairedPortal);
      D2Common::DUNGEON::Dungeon::ToggleHasPortalFlagRoom(pRoom, 1);
      return;
    }
}

// Validates and executes a gold-drop request: confirms the requester matches the acting player, checks the requested amount against current gold and inventory gold limit, spawns gold pile units via DROP_SpawnGoldPiles, marks them owned by the player, and deducts each pile's value from the player's UNITSTAT_gold.
BOOL __fastcall GOLD_DropGoldFromInventory(::SGAMEDATA * pGame, D2UnitStrc * pUnit, DWORD dwRequesterId, uint32_t nGoldAmount) {
    eD2UnitType eUnitType;
    int nPlayerGold;
    D2UnitStrc* pGoldPiles[32];
    POINT ptCoords;
    D2UnitStrc* pRequester = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_PLAYER, dwRequesterId);
    if (pRequester != pUnit) {
      return 0;
    }

    int i = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_gold, 0);
    uint32_t nClampedGold = nGoldAmount;
    if (!((int)nGoldAmount <= i && (int)nGoldAmount >= 0)) {
      return 0;
    }

    uint32_t nGoldLimit = D2Common::Units::GetInventoryGoldLimit(pUnit);
    if ((int)nClampedGold > (int)nGoldLimit) {
      return 0;
    }
    if (nClampedGold <= 0) {
      return 1;
    }

    D2Common::Units::GetCoords(pUnit, &ptCoords);
    if (nClampedGold > 2000000000) {
      nClampedGold = 2000000000;
    }

    i = 0;
    dwRequesterId = 0;
    ITEMS::Items::Drop::DROP_SpawnGoldPiles(pGame, pUnit, nClampedGold, pGoldPiles, (int*)&dwRequesterId, 0x20);
    if (!(dwRequesterId && (int)dwRequesterId > 0)) {
      return 1;
    }

    do {
      int nItemGold;
      pRequester = pGoldPiles[i];
      if (pUnit) {
        eUnitType = D2Client::Units::GetType(pUnit);
        if (eUnitType == UNIT_PLAYER) {
          D2Common::Units::StoreOwner(pRequester, pUnit);
        }
      }

      nItemGold = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pRequester, UNITSTAT_gold, 0);
      nPlayerGold = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_gold, 0);
      GAME::Server::SetStat(pUnit, UNITSTAT_gold, nPlayerGold - nItemGold);
      i++;
    } while (i < (int)dwRequesterId);

    return 1;
}

uint32_t __fastcall CheckItemMovePermission(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem) {
    uint32_t bCanMove;
    D2UnitDataPlayerStrc* pPlayerData;
    uint32_t nInteractUnitId;
    eD2UnitType eInteractUnitType;
    BOOL bHasInteraction = UNIT::SUnit::GetInteractInfo(pUnit, &eInteractUnitType, &nInteractUnitId);
    if (bHasInteraction) {
      D2UnitStrc* pInteractUnit;
      pInteractUnit = UNIT::SUnit::FindUnitFromTable(pGame, eInteractUnitType, nInteractUnitId);
      if (pInteractUnit) {
        switch (eInteractUnitType) {
          case UNIT_PLAYER:
            {
              bCanMove = PlayerTrade::PLRTRADE_ValidateAndInitiateTrade(pGame, pUnit, pItem);
              return bCanMove;
            }
          case UNIT_MONSTER:
            {
              bCanMove = Monster::MonsterAI::NpcStateIsntZero(pInteractUnit, (int32_t)pUnit);
              return bCanMove;
            }
        }

        bCanMove = PlayerTrade::PLRTRADE_ValidateAndInitiateTrade(pGame, pUnit, pItem);
        return bCanMove;
      }

      UNIT::SUnit::ClearInteractInfo(pUnit);
    } else {
      pPlayerData = D2Common::Units::GetPlayerData(pUnit);
      if (!pPlayerData->dwTradeTick) {
        bCanMove = PlayerTrade::PLRTRADE_ValidateAndInitiateTrade(pGame, pUnit, pItem);
        return bCanMove;
      }
    }

    return 0;
}

