// IterateAllUnits callback: increments pArgs->nCount when the player's room is in level
// pArgs->eLevelId and the player is not in mode Death/Dead. Only user: PLAYER_CountLivingPlayersInLevel.
void __fastcall PLAYER_CountLivingPlayerInLevelCallback(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2LevelPlayerCountArgStrc * pArgs) {
    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    eD2LevelId eRoomLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    if (!(eRoomLevelId == pArgs->eLevelId && pUnit && pUnit->eAnimMode.ePlayerMode != Death && pUnit->eAnimMode.ePlayerMode != eD2PlayerAnimMode_ns::Dead)) {
      return;
    }

    pArgs->nCount++;
}

// Counts the players in level eLevelId that are not in Death/Dead mode (IterateAllUnits walks
// only pGame->pUnitList[0], the player buckets, skipping STATE_playerbody units): builds a
// D2LevelPlayerCountArgStrc {eLevelId, 0} on the stack, runs IterateAllUnits with
// PLAYER_CountLivingPlayerInLevelCallback and returns nCount.
// No references in 1.14d. It counts; it finds no unit.
int32_t __fastcall PLAYER_CountLivingPlayersInLevel(::SGAMEDATA * pGame, eD2LevelId eLevelId) {
    D2LevelPlayerCountArgStrc sArgs;
    sArgs.nCount = 0;
    sArgs.eLevelId = eLevelId;
    UNIT::SUnit::IterateAllUnits(pGame, (fpSUnitIterateCallback)PLAYER_CountLivingPlayerInLevelCallback, &sArgs);
    return sArgs.nCount;
}

